const input = $input.first().json;

// Exact response structure returned by OpenAI "Message a model"
// in this n8n 2.33.6 setup:
//
// {
//   "output": [
//     {
//       "content": [
//         {
//           "type": "output_text",
//           "text": "```json ... ```"
//         }
//       ]
//     }
//   ]
// }

const content = input.output?.[0]?.content?.[0]?.text;

if (!content) {
  throw new Error(
    'OpenAI response text not found at output[0].content[0].text'
  );
}

// Remove ```json and ``` wrappers
const jsonText = content
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let analysis;

try {
  analysis = JSON.parse(jsonText);
} catch (error) {
  throw new Error(
    'OpenAI returned invalid JSON:\n\n' +
    jsonText +
    '\n\nParser error: ' +
    error.message
  );
}

return [
  {
    json: analysis
  }
];

const analysis = $('Parse AI Analysis').first().json;
const input = $input.first().json;

const html = input.output?.[0]?.content?.[0]?.text || '';

if (!html) {
  throw new Error(
    'Attorney HTML report not found in OpenAI response.\n\n' +
    JSON.stringify(input, null, 2)
  );
}

const originalFileName =
  $('When Contract Added').first().json.name || 'Contract.pdf';

const safeName = originalFileName
  .replace(/\.pdf$/i, '')
  .replace(/[^a-zA-Z0-9-_ ]/g, '_');

return [
  {
    json: {
      fileName: `${safeName} - Contract Review.pdf`,
      html: html,
      riskScore: analysis.risk_score ?? 0,
      overallRisk: analysis.overall_risk ?? 'Unknown',
      contractType: analysis.contract_type ?? 'Contract',
      originalFileName: originalFileName
    }
  }
];

